const relativePath=__taskArgs[0];
if(!relativePath||!/^source-models\/kicad\/[A-Za-z0-9_.\/-]+\.step$/.test(relativePath)||relativePath.includes('..'))throw new Error('Reviewed 3D source path required');
const project=await eda.dmt_Project.getCurrentProjectInfo();
const libraryUuid=await eda.lib_LibrariesList.getProjectLibraryUuid();
if(libraryUuid!=='project')throw new Error('Only the current STM32 project library is permitted');
const path='C:/Dev/EasyEDA/EasyEDA-Project/STM32H747 board/output/3d-models-20261018/'+relativePath;
const file=await eda.sys_FileSystem.readFileFromFileSystem(path);
if(!file||file.size<1000)throw new Error('STEP source not read');
const header=(await file.text()).slice(0,100);
if(!header.includes('ISO-10303-21'))throw new Error('Not a STEP source');
const stem=relativePath.split('/').pop().replace(/\.step$/,'');
const existing=await eda.lib_3DModel.search(stem,libraryUuid,undefined,50,1);
if(existing.length)throw new Error('A matching project model already exists; inspect before importing again: '+JSON.stringify(existing));
const ESYS_Unit={MILLIMETER:'mm'};
const uuids=await eda.lib_3DModel.create(libraryUuid,file,[],ESYS_Unit.MILLIMETER);
if(!Array.isArray(uuids)||uuids.length!==1)throw new Error('Expected exactly one imported STEP model: '+JSON.stringify(uuids));
const model=await eda.lib_3DModel.get(uuids[0],libraryUuid);
if(!model||model.uuid!==uuids[0])throw new Error('Imported model readback failed');
return {projectUuid:project.uuid,libraryUuid,path,sourceBytes:file.size,uuids,model};
